  "verdict": "request_changes",
  "summary": "Sorting implementation does not preserve original order for tickets with equal priority, violating the stability requirement of the contract.",
  "findings": [
    {
      "finding_id": "F001",
      "file": "candidate.py",
      "line_start": 2,
